const vm = require('node:vm');
const code = fs.readFileSync('web/level-select.js', 'utf8');
let fetchCalled = 0;
function makeEl(id) {
  return { id, hidden: false, className: '', childNodes: [], appendChild(c) { this.childNodes.push(c); }, removeChild(c) { this.childNodes = this.childNodes.filter(x => x !== c); }, get firstChild() { return this.childNodes[0] ?? null; } };
}
